import ConfirmModal from '../../Components/ConfirmModal.vue'
import PageHeader from '../../Components/PageHeader.vue'
import StatusBadge from '../../Components/StatusBadge.vue'
import FormErrorSummary from '../../Components/FormErrorSummary.vue'
type LinkItem = { url: string | null; label: string; active: boolean }; type Member = { id: string | number; name?: string; email: string; role?: string }; type Invitation = { id: string | number; email: string; role?: string; created_at?: string; expires_at?: string }; type Paginator<T> = { data?: T[]; links?: LinkItem[]; from?: number | null; to?: number | null; total?: number | null }
const props = withDefaults(defineProps<{ members?: Member[] | Paginator<Member>; invitations?: Invitation[] | Paginator<Invitation>; usage?: { current?: number; limit?: number }; locked?: boolean }>(), { members: () => [], invitations: () => [], usage: () => ({}), locked: false })
const page = usePage<{ flash?: { success?: string } }>(); const inviteForm = useForm({ email: '', role: '' }); const removeForm = useForm({}); const removingId = shallowRef<string | number | null>(null); const inviteStatus = shallowRef('')
const memberToRemove = shallowRef<Member | null>(null)
const members = computed(() => normalize(props.members)); const invitations = computed(() => normalize(props.invitations))
function normalize<T>(value: T[] | Paginator<T>): T[] & Paginator<T> { return Array.isArray(value) ? value : Object.assign([...(value?.data || [])], value || {}) }
function invite() { inviteStatus.value = 'Enviando convite…'; inviteForm.post('/settings/team/invitations', { preserveScroll: true, onSuccess: () => { inviteForm.reset(); inviteStatus.value = 'Convite enviado.' }, onError: () => { inviteStatus.value = 'Não foi possível enviar o convite. Tente novamente.' } }) }
function removeMember(member: Member) { if (!removeForm.processing) memberToRemove.value = member }
function confirmRemoveMember() { const member = memberToRemove.value; if (!member) return; memberToRemove.value = null; removingId.value = member.id; removeForm.post(`/settings/team/members/${member.id}/remove`, { preserveScroll: true, onFinish: () => { removingId.value = null } }) }
</script>
