      <section class="panel min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words"><div class="panel-heading mb-6 flex flex-wrap items-start justify-between gap-4 [&_p]:mt-2 [&_p]:text-sm [&_p]:leading-6 [&_p]:text-td-body"><div><h2>Uso</h2><p>{{ props.usage.current ?? members.length }} de {{ props.usage.limit ?? '—' }} usuários</p></div></div><svg class="h-3 w-full overflow-hidden rounded-full bg-td-icon" viewBox="0 0 100 3" preserveAspectRatio="none" role="progressbar" aria-label="Uso do limite de usuários" :aria-valuenow="props.usage.current || members.length" :aria-valuemax="props.usage.limit || 0"><rect :width="props.usage.limit ? Math.min(100, ((props.usage.current || members.length) / props.usage.limit) * 100) : 0" height="3" class="fill-td-primary" /></svg></section>
      <form v-if="!props.locked" class="panel stack min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words grid grid-cols-12 gap-6 [&>*]:col-span-12" @submit.prevent="invite"><div class="panel-heading mb-6 flex flex-wrap items-start justify-between gap-4 [&_p]:mt-2 [&_p]:text-sm [&_p]:leading-6 [&_p]:text-td-body"><div><h2>Novo convite</h2><p>O convite expira e só pode ser aceito pelo destinatário.</p></div></div><FormErrorSummary :errors="inviteForm.errors" /><div class="form-grid grid min-w-0 grid-cols-12 gap-x-7 gap-y-6"><div class="field-group col-span-12 grid min-w-0 content-start gap-3 sm:col-span-6"><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="invite-email">E-mail</label><input id="invite-email" v-model="inviteForm.email" class="form-input w-full min-w-0 scroll-mt-28 rounded-lg border border-td-border bg-transparent px-4 py-2.5 text-sm leading-5 text-td-ink outline-none placeholder:text-td-body/70 focus:border-td-primary focus-visible:ring-2 focus-visible:ring-td-primary/15 disabled:cursor-not-allowed disabled:bg-td-soft disabled:text-td-body file:mr-3 file:rounded file:border-0 file:bg-td-soft file:px-3 file:py-1 file:text-sm file:text-td-primary" type="email" autocomplete="email" :disabled="inviteForm.processing" required :aria-invalid="Boolean(inviteForm.errors.email)" placeholder="nome@empresa.com.br" /><p v-if="inviteForm.errors.email" class="field-error text-sm leading-5 text-td-red" role="alert">{{ inviteForm.errors.email }}</p></div><div class="field-group col-span-12 grid min-w-0 content-start gap-3 sm:col-span-6"><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="invite-role">Papel</label><FormSelect id="invite-role" v-model="inviteForm.role" required placeholder="Selecione um papel" :disabled="inviteForm.processing" 