      <p v-if="inviteStatus" class="status-message my-5 flex min-w-0 items-start gap-3 rounded-lg border border-td-green/25 bg-td-green/5 p-4 text-sm leading-6 text-td-green-ink [&_svg]:size-5 [&_svg]:shrink-0" role="status" aria-live="polite">{{ inviteStatus }}</p><button v-if="inviteForm.hasErrors" class="btn-text inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg px-3 py-2 text-td-primary hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="button" :disabled="inviteForm.processing" @click="invite">Tentar novamente</button>
