xt-sm leading-6 text-td-body">Nenhum membro adicional ainda.</p><nav v-if="members.links?.length" class="pagination mt-6 flex flex-col gap-4 text-sm sm:flex-row sm:items-center sm:justify-between" aria-label="Paginação de membros"><span>{{ members.from || 0 }}–{{ members.to || 0 }} de {{ members.total || 0 }}</span><div class="pagination__actions flex max-w-full flex-wrap gap-2"><template v-for="link in members.links" :key="`member-${link.label}`"><Link v-if="link.url" class="btn-secondary inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-td-border bg-white px-4 py-2.5 text-sm leading-5 text-td-ink hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" :class="{ 'pagination__current !border-td-primary !bg-td-primary !text-white': link.active }" :href="link.url" preserve-scroll preserve-state>{{ paginationLabel(link.label) }}</Link><span v-else class="btn-secondary pagination__disabled inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-td-border bg-white px-4 py-2.5 text-sm leading-5 text-td-ink hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0 pointer-events-none opacity-50" aria-hidden="true">{{ paginationLabel(link.label) }}</span></template></div></nav></section>
