-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-td-border bg-white px-4 py-2.5 text-sm leading-5 text-td-ink hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" :class="{ 'pagination__current !border-td-primary !bg-td-primary !text-white': link.active }" :href="link.url" preserve-scroll preserve-state>{{ paginationLabel(link.label) }}</Link><span v-else class="btn-secondary pagination__disabled inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-td-border bg-white px-4 py-2.5 text-sm leading-5 text-td-ink hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0 pointer-events-none opacity-50" aria-hidden="true">{{ paginationLabel(link.label) }}</span></template></div></nav></section>
    </div>
  </AppShell>
  <ConfirmModal :open="Boolean(memberToRemove)" title="Excluir membro" :message="`Deseja remover ${memberToRemove?.name || memberToRemove?.email || 'este membro'} da equipe?`" :busy="removeForm.processing" @cancel="memberToRemove = null" @confirm="confirmRemoveMember" />
